import{_ as t,a as o,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 63 Thank you, doctor.","description":"学习 must not 与 do not have to，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 63 Thank you, doctor.","description":"学习 must not 与 do not have to，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 must not 与 do not have to，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 62 What's the matter with them?","link":"/life/english/new-concept/book-1/unit-03/lesson-062"},"next":{"text":"第一册：英语初阶 · Lesson 64 You mustn't ...","link":"/life/english/new-concept/book-1/unit-03/lesson-064"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 62 What's the matter with them?","link":"/life/english/new-concept/book-1/unit-03/lesson-062"},"next":{"text":"第一册：英语初阶 · Lesson 64 You mustn't ...","link":"/life/english/new-concept/book-1/unit-03/lesson-064"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-063.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-063.md"}`),i={name:"life/english/new-concept/book-1/unit-03/lesson-063.md"};function s(l,e,r,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-63-thank-you-doctor" tabindex="-1">第一册：英语初阶 · Lesson 63 Thank you, doctor. <a class="header-anchor" href="#第一册-英语初阶-·-lesson-63-thank-you-doctor" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 63 Thank you, doctor.&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-064">配套课 Lesson 64</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>区分禁止和没有必要 本课要掌握must not 与 do not have to，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>remain</td><td>/rɪˈmeɪn/</td><td>v.</td><td>保持；留下</td><td>remain quiet</td></tr><tr><td>noise</td><td>/nɔɪz/</td><td>n.</td><td>噪声</td><td>make noise</td></tr><tr><td>rule</td><td>/ruːl/</td><td>n.</td><td>规定</td><td>follow a rule</td></tr><tr><td>quiet</td><td>/ˈkwaɪət/</td><td>adj.</td><td>安静的</td><td>keep quiet</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>must not enter — 禁止进入</li><li>do not have to wait — 不必等候</li></ul><h2 id="语法讲解-must-not-与-do-not-have-to" tabindex="-1">语法讲解：must not 与 do not have to <a class="header-anchor" href="#语法讲解-must-not-与-do-not-have-to" aria-label="Permalink to &quot;语法讲解：must not 与 do not have to&quot;">​</a></h2><p>must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>You must not make noise in this room.</p></blockquote><p>你不得在这个房间制造噪声。</p><p>Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>mustn&#39;t 不表示“不必”；免除义务应使用 don&#39;t have to。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“You must not make noise in this room.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>You must not make noise in this room. You do not have to wait outside.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“区分禁止和没有必要”写两至三句，再读给同伴听。至少使用一次must not 与 do not have to，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。 Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>表达禁止：You ___ not enter.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must</p><p><strong>解析：</strong> 按本课规则判断：must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“你不得在这个房间制造噪声。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> You must not make noise in this room.</p><p><strong>解析：</strong> Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：You do not have to wait outside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 你不必在外面等候。</p><p><strong>解析：</strong> Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：must not 与 do not have to。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-062">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-064">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
